from math import pow

def climbing_stairs(n):
    def fib(n):
        if n == 1:
            return 1
        if n == 2:
            return 2
        return fib(n - 1) + fib(n - 2)

    return fib(n)

if __name__ == '__main__':
    n = int(input())
    print(climbing_stairs(n))

def racecar(sentence):

    sentence = sentence.replace(",", "");
    sentence = sentence.replace(".", "");
    sentence = sentence.replace("!", "");
    sentence = sentence.replace("?", "");
    sentence = sentence.replace(":", "");
    sentence = sentence.replace(";", "");
    sentence = sentence.replace("'", "");
    sentence = sentence.replace('"', "");
    sentence = sentence.replace("(", "");
    sentence = sentence.replace(")", "");
    sentence = sentence.replace("-", "");

    words = sentence.split(" ")

    winners = []
    for word in words:
        if word == word[::-1]:
            winners.append(word)

    return winners

print(racecar("Was it a car or a cat I saw?"))

